const examplePool = [
  "Okullar ne zaman açılacak?",
  "Dolunay ne zaman?",
  "Fenerbahçe en son ne zaman şampiyon oldu?",
  "Tavuk ne zaman bozulur?",
  "Cemre ne zaman düşer?",
  "Hamilelik testi ne zaman yapılır?",
  "Emlak vergisi ne zaman ödenir?",
  "Meteor yağmuru ne zaman izlenir?",
  "Bebekler ne zaman yürür?",
  "Kurban Bayramı ne zaman?",
  "Araç muayenesi ne zaman yapılır?",
  "Yoğurt ne zaman mayalanır?",
  "Beşiktaş maçı ne zaman?",
  "YKS ne zaman?",
  "Ağaçlar ne zaman budanır?",
  "Atatürk ne zaman vefat etti?",
  "Barış Manço ne zaman vefat etti?"
];

const input = document.getElementById("searchInput");
const results = document.getElementById("searchResults");
const form = document.getElementById("searchForm");

function renderResults(query){
  if(!input || !results) return;
  const q = query.trim().toLocaleLowerCase("tr-TR");
  results.innerHTML = "";
  if(!q) return;
  const found = questions.filter(item =>
    item.title.toLocaleLowerCase("tr-TR").includes(q) ||
    item.cat.toLocaleLowerCase("tr-TR").includes(q)
  ).slice(0, 10);
  if(found.length === 0){
    results.innerHTML = `<div class="result-item"><strong>Henüz kayıt bulunamadı.</strong><small>Bu soru yeni içerik havuzuna eklenebilir.</small></div>`;
    return;
  }
  results.innerHTML = found.map(item =>
    `<a class="result-item" href="${item.url}"><strong>${item.title}</strong><small>${item.cat}</small></a>`
  ).join("");
}
function shuffleExamples(){
  const buttons = Array.from(document.querySelectorAll("[data-fill]"));
  const pool = [...examplePool].sort(() => Math.random() - 0.5);
  buttons.forEach((btn, i) => {
    const value = pool[i % pool.length];
    btn.dataset.fill = value;
    btn.textContent = value.replace(" ne zaman", "").replace("?", "").slice(0, 22);
  });
}
function renderDynamicMiniPills(){
  const wrap = document.getElementById("dynamicMiniPills");
  if(!wrap) return;
  const pool = [...examplePool].sort(() => Math.random() - 0.5).slice(0, 3);
  wrap.innerHTML = pool.map(q => `<button type="button" data-mini-fill="${q}">${q}</button>`).join("");
  wrap.querySelectorAll("[data-mini-fill]").forEach(btn => {
    btn.addEventListener("click", () => {
      input.value = btn.dataset.miniFill;
      renderResults(input.value);
      input.focus();
    });
  });
}
if(form){ form.addEventListener("submit", e => { e.preventDefault(); renderResults(input.value); }); }
if(input){ input.addEventListener("input", () => renderResults(input.value)); }
document.addEventListener("DOMContentLoaded", () => {
  shuffleExamples();
  renderDynamicMiniPills();
  document.querySelectorAll("[data-fill]").forEach(btn => {
    btn.addEventListener("click", () => {
      input.value = btn.dataset.fill;
      renderResults(input.value);
      input.focus();
    });
  });
});
